import{_ as i,c as r,o as s,ae as a}from"./chunks/framework.Bw0Gm4PQ.js";const h=JSON.parse('{"title":"ADDRESSING RISKS FROM WILMERHALE","description":"","frontmatter":{"title":"ADDRESSING RISKS FROM WILMERHALE","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/03/addressing-risks-from-wilmerhale/","publishDate":"2025-03-27T18:34:15-04:00"},"headers":[],"relativePath":"executive-orders/2025-03-27-addressing-risks-from-wilmerhale.md","filePath":"executive-orders/2025-03-27-addressing-risks-from-wilmerhale.md"}'),t={name:"executive-orders/2025-03-27-addressing-risks-from-wilmerhale.md"};function l(n,e,o,c,d,m){return s(),r("div",null,e[0]||(e[0]=[a('<h1 id="addressing-risks-from-wilmerhale" tabindex="-1">ADDRESSING RISKS FROM WILMERHALE <a class="header-anchor" href="#addressing-risks-from-wilmerhale" aria-label="Permalink to &quot;ADDRESSING RISKS FROM WILMERHALE&quot;">​</a></h1><p>Published: Thursday, March 27, 2025</p><ul><li>The President has issued an executive order to address risks posed by law firms, particularly &quot;Big Law&quot; firms, that act against American interests.</li><li>It highlights concerns about law firms engaging in activities that threaten public safety, national security, and constitutional freedoms.</li><li>The Executive Order specifically targets Wilmer Cutler Pickering Hale and Dorr LLP (WilmerHale) for alleged abuses of its pro bono practice and partisan conduct.</li><li>Accusations against WilmerHale include: <ul><li>Discrimination based on race</li><li>Obstruction of illegal immigration prevention measures</li><li>Supporting noncitizen voting</li><li>Weaponizing the justice system through influential hires like Robert Mueller.</li></ul></li><li>The order mandates the following: <ul><li>Suspension of security clearances for WilmerHale employees until a review is complete.</li><li>The Office of Management and Budget must identify and cease government support and contracts with WilmerHale.</li><li>Federal contractors must disclose any business dealings with WilmerHale related to government contracts.</li><li>Agencies must review contracts with WilmerHale and take steps, including possible terminations, to align with national interests.</li><li>Agencies are instructed to limit access to federal buildings for WilmerHale employees if it threatens national security.</li><li>Hiring of WilmerHale employees by government agencies requires a waiver.</li></ul></li><li>The order emphasizes compliance with applicable laws and does not create any new enforceable rights.</li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/03/addressing-risks-from-wilmerhale/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/03/addressing-risks-from-wilmerhale/</a></p>',4)]))}const g=i(t,[["render",l]]);export{h as __pageData,g as default};
